INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21301, 'Amos 4:6', 'Amos', 4, 6, '&nbsp;”ما په هر ښار لوږه راوسته او په هر کلى مې قحط راوستو. خو بيا هم تاسو ما ته واپس رانۀ غلئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21302, 'Amos 4:7', 'Amos', 4, 7, '&nbsp;”کله چې ستاسو فصل ته د باران سخت ضرورت وو نو ما د دې ورېدل بند کړل. ما په يو کلى باران وورولو خو په بل کلى مې ونۀ ورولو. په يو پټى باران وشو، خو بل پټے اوچ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21303, 'Amos 4:8', 'Amos', 4, 8, '&nbsp;خلق د اوبو په لټون کښې کلى په کلى سرګردانه ګرځېدل، خو هلته هم د څښلو دپاره کافى اوبۀ نۀ وې. خو بيا هم تاسو ما ته واپس رانۀ غلئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21304, 'Amos 4:9', 'Amos', 4, 9, '&nbsp;”ما ستاسو په فصلونو او د انګورو په باغونو تِليا او بيمارى راوسته. د قحطۍ مُلخانو ستاسو د اينځرو او د زيتُونو ونې وخوړلې. خو تاسو بيا هم ما ته واپس رانۀ غلئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21305, 'Amos 4:10', 'Amos', 4, 10, '&nbsp;”ما په تاسو وباګانې راوستلې څنګه مې چې په مِصريانو رالېږلې وې. ما ستاسو زلمى په تُوره ووژل، او ستاسو ټول آسونه مې بوتلل. ما ستاسو په لښکر ګاه کښې ستاسو پوزې د مړو د بوئ نه ډکې کړې. خو تاسو بيا هم ما ته واپس رانۀ غلئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21306, 'Amos 4:11', 'Amos', 4, 11, '&nbsp;”ما ستاسو څۀ خلق تباه کړل لکه څنګه چې مې د سدوم او عموره خلق تباه کړى وُو. تاسو د هغه نيم سوزېدونکى لرګى په شان وئ کوم چې د اور نه راښکلے شوے وى، خو تاسو بيا هم ما ته راونۀ ګرځېدئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21307, 'Amos 4:12', 'Amos', 4, 12, '&nbsp;”نو اے بنى اِسرائيلو، تاسو به وګورئ چې زۀ درسره څۀ کوم، نو ځکه زۀ درسره داسې کوم، نو د خپل خُدائ پاک سره د ملاقات دپاره تيار شئ، اے بنى اِسرائيلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21308, 'Amos 4:13', 'Amos', 4, 13, '&nbsp;ځکه چې مالِک خُدائ هم هغه دے چا چې غرونه پېدا کړى دى، او هوا يې پېدا کړې ده، او خپل خيالات بنى آدم ته څرګندوى. هغه د سحر رڼا په تيارۀ بدلوى او د زمکې په اوچتو ځايونو باندې ګرځى. د هغۀ نوم مالِک خُدائ پاک، ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21309, 'Amos 5:1', 'Amos', 5, 1, '&nbsp;اے بنى اِسرائيلو، زۀ چې د غم کومه سندره ستاسو په حقله وايم، هغې ته غوږ ونيسئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21310, 'Amos 5:2', 'Amos', 5, 2, '&nbsp;”پېغله بنى اِسرائيل راغورزېدله ده، بيا به هيڅکله دوباره نۀ راپاڅى. هغه په خپله زمکه يواځې راغورزېدلې ده چې هيڅوک به يې دوباره ونۀ دروى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21311, 'Amos 5:3', 'Amos', 5, 3, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى، ”د بنى اِسرائيلو د يو ښار نه چې زر فوجيان د جنګ دپاره ولېږلے شى، نو صرف سل به په کښې پاتې شى، او چې د يو بل ښار نه يې سل فوجيان ولېږلے شى، نو صرف لس به په کښې واپس راشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21312, 'Amos 5:4', 'Amos', 5, 4, '&nbsp;مالِک خُدائ د بنى اِسرائيلو قوم ته داسې فرمائى، ”ما ولټوئ نو تاسو به ژوندى پاتې شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21313, 'Amos 5:5', 'Amos', 5, 5, '&nbsp;مۀ بيت‌ايل لټوئ، او مۀ جِلجال ته ځئ، او مۀ بيرسبع ته سفر کوئ ځکه چې د جِلجال خلق به يقيناً جلاوطن کړے شى، او بيت‌ايل به نيست و نابود کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21314, 'Amos 5:6', 'Amos', 5, 6, '&nbsp;د مالِک خُدائ طلبګار شئ نو ژوندى به پاتې شئ، ګنې هغه به د يوسف خاندان لکه د اور وسوزوى، او بيت‌ايل به خاورې ايرې کړى او هيڅوک به داسې نۀ وى چې هغه اور مړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21315, 'Amos 5:7', 'Amos', 5, 7, '&nbsp;تاسو هغه څوک يئ چې اِنصاف په ګنډير بدلوئ او صداقت په زمکه راغورزوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21316, 'Amos 5:8', 'Amos', 5, 8, '&nbsp;هغه چا چې ستورى پېدا کړى دى، چا چې د ستورو غومپک پېدا کړے دے. او څوک چې تيارۀ د سحر په رڼا بدلوى، او د ورځې رڼا په شپه بدلوى. څوک چې د سمندر اوبۀ راوغواړى او د زمکې په مخ يې وراړوى، د هغۀ نوم مالِک خُدائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21317, 'Amos 5:9', 'Amos', 5, 9, '&nbsp;هغه په زورَورو خلقو سمدستى تباهى راولى او د هغوئ مضبوطې قلعه ګانې تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21318, 'Amos 5:10', 'Amos', 5, 10, '&nbsp;تاسو د هغوئ نه نفرت کوئ څوک چې په عدالت کښې اِنصاف کوى، او هغوئ سپکوئ څوک چې حقيقت وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21319, 'Amos 5:11', 'Amos', 5, 11, '&nbsp;تاسو په غريبانانو ظلم کوئ او د هغوئ په غله د حد نه زيات ټيکس لګوئ. نو په دې وجه اګر کۀ تاسو د کاڼو نه ښائسته کورونه جوړ کړى دى خو تاسو به په هغې کښې نۀ اوسېږئ، اګر کۀ تاسو د انګورو ډک باغونه کَرلى دى خو تاسو به د هغې مے ونۀ څښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21320, 'Amos 5:12', 'Amos', 5, 12, '&nbsp;ما ته پته ده چې ستاسو جرمونه څومره ډېر دى او ستاسو ګناهونه څومره لوئې دى. تاسو په صادقانو ظلم کوئ او رشوتونه اخلئ او د غريبانانو سره په عدالت کښې اِنصاف نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21321, 'Amos 5:13', 'Amos', 5, 13, '&nbsp;نو په دې وجه هوښيار انسان په داسې وخت کښې خاموشه وى، ځکه چې زمانه ډېره خرابه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21322, 'Amos 5:14', 'Amos', 5, 14, '&nbsp;د ښو لټون کوئ او بدو پسې مۀ ګرځئ نو تاسو به ژوندى پاتې شئ. نو بيا به مالِک خُدائ، ربُ الافواج ستاسو مل وى، لکه څنګه چې تاسو دعوىٰ کوئ چې هغه ستاسو مل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21323, 'Amos 5:15', 'Amos', 5, 15, '&nbsp;د بدو نه نفرت کوئ او د نېکۍ سره مينه کوئ، او په عدالت کښې اِنصاف قائم کړئ. نو کېدے شى چې مالِک خُدائ، ربُ الافواج، د بنى اِسرائيلو په باقى پاتې شوو خلقو رحم وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21324, 'Amos 5:16', 'Amos', 5, 16, '&nbsp;نو ځکه مالِک خُدائ، ربُ الافواج قادر مطلق خُدائ فرمائى، ”په ټولو کوڅو کښې به ژړاګانې وى او په هر چوک کښې به د مړو وير وى. زمينداران د ماتم کولو دپاره راوغوښتلے شى او کسبى ماتم کوونکى به د ژړا دپاره راوغوښتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21325, 'Amos 5:17', 'Amos', 5, 17, '&nbsp;د انګورو په ټولو باغونو کښې به ژړاګانې وى، ځکه چې زۀ به ستاسو د سزا دپاره ستاسو په مينځ کښې تېر شم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21326, 'Amos 5:18', 'Amos', 5, 18, '&nbsp;په تاسو دې افسوس وى څوک چې د مالِک خُدائ د قيامت د ورځې ارمان کوئ. تاسو ولې د مالِک خُدائ د قيامت د ورځې ارمان کوئ؟ دا به ستاسو دپاره د رڼا نه بلکې د تيارې ورځ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21327, 'Amos 5:19', 'Amos', 5, 19, '&nbsp;دا به داسې وى لکه چې څوک د ازمرى نه تښتى او مېلو ته مخامخ شى، او يا خپل کور ته لاړ شى او لاس په دېوال باندې کېږدى او مار يې وچيچى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21328, 'Amos 5:20', 'Amos', 5, 20, '&nbsp;آو، د مالِک خُدائ د قيامت ورځ به تيارۀ او د نااُميدۍ سبب وى. دې کښې به د خوشحالۍ يا د اُميد رڼا نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21329, 'Amos 5:21', 'Amos', 5, 21, '&nbsp;”زۀ ستاسو اخترونو نه سخت نفرت کوم او ستاسو مذهبى محفلونه ما ته هيڅ خوشحالى نۀ راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21330, 'Amos 5:22', 'Amos', 5, 22, '&nbsp;اګر کۀ تاسو ما ته سوزېدونکې نذرانې او د غلې نذرانې راوړئ، نو زۀ به دا قبولې نۀ کړم. اګر کۀ تاسو ما ته د څورب ځناورو د خپلې خوښې نذرانې پېش کړئ زۀ به دې ته هيڅ نظر ونۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21331, 'Amos 5:23', 'Amos', 5, 23, '&nbsp;د خپلو سندرو شور زما نه اخوا کړئ، زۀ ستاسو د رباب ساز اورېدل نۀ غواړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21332, 'Amos 5:24', 'Amos', 5, 24, '&nbsp;د دې په ځائ دې اِنصاف لکه د اوبو د چپو په شان وبهيږى، او صداقت د هغه سيند په شان چې هيڅکله نۀ اوچيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21333, 'Amos 5:25', 'Amos', 5, 25, '&nbsp;اے بنى اِسرائيلو، کله چې تاسو د څلوېښتو کالو دپاره په بيابان کښې وئ نو ما ته مو کله قربانۍ او نذرانې راوړې دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21334, 'Amos 5:26', 'Amos', 5, 26, '&nbsp;خو اوس چې تاسو د سکوت بُت عبادت وکړو کوم چې تاسو خپل بادشاه منئ، او کيوان چې ستاسو په ستورو کښې معبود دے، نو تاسو به دا بُتان په خپلو اوږو ګرځوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21335, 'Amos 5:27', 'Amos', 5, 27, '&nbsp;نو په دې وجه به زۀ تاسو د دمشق نه هم اخوا جلاوطن کړم،“ مالِک خُدائ فرمائى، د چا نوم چې قادر مطلق خُدائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21336, 'Amos 6:1', 'Amos', 6, 1, '&nbsp;”په تاسو دې افسوس وى څوک چې په صيون کښې په آرام پراتۀ يئ، او په تاسو هم څوک چې خپل ځان د سامريې په غر محفوظ ګڼئ. تاسو په بنى اِسرائيلو کښې نامتو او مشهور يئ، چا له چې خلق د مدد غوښتلو دپاره ورځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21337, 'Amos 6:2', 'Amos', 6, 2, '&nbsp;تاسو کلنه ښار ته لاړ شئ او وګورئ چې هلته څۀ شوى دى. بيا د حمات لوئ ښار ته لاړ شئ، او بيا په فلستيه کښې د جات ښار ته ورکوز شئ. تاسو خو د هغوئ نه څۀ زيات ښۀ نۀ يئ؟ ولې ستاسو علاقه د هغوئ نه لويه ده څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21338, 'Amos 6:3', 'Amos', 6, 3, '&nbsp;تاسو دا نۀ منئ چې د مصيبت هغه ورځ به راشى، بلکې تاسو د بې‌اِنصافۍ حکومت قائم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21339, 'Amos 6:4', 'Amos', 6, 4, '&nbsp;په تاسو افسوس چې د هاتى په غاښونو په ښائسته کړے شوى پالنګونو کښې اودۀ کېږئ او په حُجره کښې په کټونو کښې غزېږئ. تاسو د خوراک دپاره د خپلو رمو نه د خوښې ګډورى او د خپل مال نه څربه سخى خوښوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21340, 'Amos 6:5', 'Amos', 6, 5, '&nbsp;تاسو په سريندو کښې بې‌مطلبه سازونه غږوئ او خپل ځان د داؤد سره د برابرولو کوشش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21341, 'Amos 6:6', 'Amos', 6, 6, '&nbsp;تاسو د ميو ډک جامونه څښئ او اعلىٰ عطر لګوئ، خو تاسو د خپل مُلک په تباهۍ څۀ خفګان نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21342, 'Amos 6:7', 'Amos', 6, 7, '&nbsp;نو ځکه تاسو به اولنى خلق يئ چې جلاوطن به شئ، او ستاسو مېلې او غزېدل به ختم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21343, 'Amos 6:8', 'Amos', 6, 8, '&nbsp;قادر مطلق خُدائ په خپل ذات قسم کړے دے. مالِک خُدائ، ربُ الافواج فرمائى، ”زۀ د يعقوب د غرور نه کرکه کوم، او د هغۀ مضبوطو قلعه ګانو نه نفرت کوم. زۀ به ښار او په دې کښې چې هر څۀ دى دشمن ته حواله کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21344, 'Amos 6:9', 'Amos', 6, 9, '&nbsp;کۀ په يو خاندان کښې لس سړى پاتې وى نو هغوئ به هم مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21345, 'Amos 6:10', 'Amos', 6, 10, '&nbsp;او چې کله د هغوئ يو خپلوان راشى څوک چې د هغوئ د مړو د دفن کولو ذمه وار وى او کور ته ورننوځى چې مړى رابهر کړى، نو هغه به د آخرى بچ شوى کس نه تپوس وکړى، ”آيا تا سره نور څوک شته؟“ نو هغه به وائى چې، ”نه،“ نو کله چې هغه ورته قسم خوړل غواړى، نو بيا به هغه ورته ووائى چې، ”چپ شه، مونږ له په کار دى چې د مالِک خُدائ نوم وانۀ خلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21346, 'Amos 6:11', 'Amos', 6, 11, '&nbsp;کله چې مالِک خُدائ حکم وکړى، نو بيا به هغه غټ او واړۀ کورونه دړې وړې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21347, 'Amos 6:12', 'Amos', 6, 12, '&nbsp;آيا آسونه په غټو کاڼو کښې منډې وهلے شى؟ آيا څوک په غوَيانو باندې سمندر قلبه کولے شى؟ خو تاسو اِنصاف په ګنډير بدل کړے دے او د صداقت مېوه مو په بدۍ بدله کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21348, 'Amos 6:13', 'Amos', 6, 13, '&nbsp;تاسو د لودبار په فتح خوشحالى کوئ، او وايئ چې، ”آيا مونږ په خپل طاقت سره قرنَيم نۀ دے نيولے څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21349, 'Amos 6:14', 'Amos', 6, 14, '&nbsp;مالِک خُدائ، ربُ الافواج په خپله فرمائى چې، ”اے بنى اِسرائيله، زۀ به ستا خلاف يو قوم درولېږم، چې په تاسو به د ليبو‌حمات نه تر عرابه وادۍ پورې ظلم کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21350, 'Amos 7:1', 'Amos', 7, 1, '&nbsp;قادر مطلق خُدائ ما ته په رويا کښې دا وښودل چې، هغۀ د قحطۍ مُلخانو لښکرې د حملې دپاره تيارولې. دا په هغه وخت کښې وشول کله چې د بادشاه د برخې وړومبے فصل رېبلے شوے وو او د دوېم فصل د راختلو وخت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21351, 'Amos 7:2', 'Amos', 7, 2, '&nbsp;ما په خپله رويا کښې وليدل چې د قحطۍ مُلخانو د زمکې ټول شينکے وخوړلو، نو بيا ما ووئيل چې، ”اے قادر مطلق خُدايه مونږ معاف کړه، ګنې مونږ به ژوندى پاتې نۀ شُو، ځکه چې د بنى اِسرائيلو قوم ډېر وړوکے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21352, 'Amos 7:3', 'Amos', 7, 3, '&nbsp;نو مالِک خُدائ خپله فېصله بدله کړه، چې، ”داسې به بيا کله ونۀ شى،“ مالِک خُدائ وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21353, 'Amos 7:4', 'Amos', 7, 4, '&nbsp;نو قادر مطلق خُدائ ما ته بله رويا وښودله، په رويا کښې ما وکتل چې هغه تيارے کوى چې خپلو خلقو له د غټ اور په ذريعه سزا ورکړى. هغه اور د سمندر بېخ وسوزولو او ټوله زمکه يې تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21354, 'Amos 7:5', 'Amos', 7, 5, '&nbsp;نو بيا ما چغې کړې، ”اے قادر مطلق خُدايه زۀ تا ته زارى کوم، بس کړه. ګنې مونږ به ژوندى پاتې نۀ شُو، ځکه چې د بنى اِسرائيلو قوم ډېر کمزورے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21355, 'Amos 7:6', 'Amos', 7, 6, '&nbsp;نو مالِک خُدائ خپله فېصله بدله کړه، چې، ”داسې به بيا کله ونۀ شى.“ مالِک قادر مطلق خُدائ دا وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21356, 'Amos 7:7', 'Amos', 7, 7, '&nbsp;نو بيا ما ته مالِک خُدائ يوه بله رويا وښودله. په دې کښې ما وليدل چې مالِک خُدائ د يو داسې دېوال په خوا کښې ولاړ وو چې د سال سره جوړ وو او د هغۀ په لاس کښې سال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21357, 'Amos 7:8', 'Amos', 7, 8, '&nbsp;او مالِک خُدائ زما نه تپوس وکړو چې، ”عاموسه، تا ته څۀ ښکارى؟“ نو ما ورته جواب ورکړو چې، ”سال.“ بيا مالِک خُدائ وفرمائيل، ”وګوره، زۀ د خپلو خلقو بنى اِسرائيلو په مينځ کښې سال لګوم، زۀ به نور د هغوئ ګناهونه پرې نۀ ږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21358, 'Amos 7:9', 'Amos', 7, 9, '&nbsp;په کومو علاقائى عبادتخانو کښې چې د اِسحاق اولاد عبادت کولو هغه به تباه شى او د بنى اِسرائيلو مقدس ځايونه به هم کنډرې شى، او زۀ به د يربعام خاندان نيست و نابود کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21359, 'Amos 7:10', 'Amos', 7, 10, '&nbsp;نو بيا د بيت‌ايل اِمام امصياه د اِسرائيل بادشاه يربعام له دا خبر ورولېږلو چې، ”عاموس د بنى اِسرائيلو په مينځ کښې ستا خلاف سازشونه جوړوى. د هغۀ وينا د برداشت نه بهر ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21360, 'Amos 7:11', 'Amos', 7, 11, '&nbsp;ځکه چې عاموس داسې فرمائى چې، يربعام به په تُوره مړ شى، او بنى اِسرائيل به د خپل مُلک نه پردى مُلک ته جلاوطن کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21361, 'Amos 7:12', 'Amos', 7, 12, '&nbsp;بيا امصياه عاموس ته ووئيل، ”اے رويا کتونکيه، دلته نه اوځه. او واپس د يهوداه مُلک ته لاړ شه. هلته خپل رزق وګټه او هلته خپلې پېشګويانې کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21362, 'Amos 7:13', 'Amos', 7, 13, '&nbsp;دلته په بيت‌ايل کښې نورې پېشګويانې مۀ کوه، ځکه چې بادشاهى محل او بادشاهى عبادتخانه دلته ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21363, 'Amos 7:14', 'Amos', 7, 14, '&nbsp;خو عاموس امصياه ته جواب ورکړو، ”نۀ زۀ پېغمبر يم او نۀ د پېغمبر زوئ يم، زۀ صرف يو شپون يم او د اينځر د ونو خيال هم ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21364, 'Amos 7:15', 'Amos', 7, 15, '&nbsp;خو مالِک خُدائ زۀ د شپونتوب نه راروان کړم او حُکم يې راکړو چې، لاړ شه او زما خلقو اِسرائيل ته پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21365, 'Amos 7:16', 'Amos', 7, 16, '&nbsp;نو بيا اوس د مالِک خُدائ کلام ته غوږ شه. تۀ وائې چې، د بنى اِسرائيل خلاف پېشګوئې مۀ کوه. او د اِسحاق د قوم خلاف تبليغ بند کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21366, 'Amos 7:17', 'Amos', 7, 17, '&nbsp;نو په دې وجه مالِک خُدائ دا فرمائى چې، ستا ښځې نه به د ښار کنجره جوړه شى، او ستا زامن او لوڼه به په تُوره مړۀ شى. ستا مُلک به ناپ کړے شى او تقسيم به شى، او تۀ به په خپله په يو ناپاک مُلک کښې مړ شې. او بنى اِسرائيل به د خپل مُلک نه پردى مُلک ته جلاوطن کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21367, 'Amos 8:1', 'Amos', 8, 1, '&nbsp;ما ته مالِک خُدائ يوه بله رويا وښودله. په دې کښې مې د پخې مېوې يوه ټوکرۍ وليدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21368, 'Amos 8:2', 'Amos', 8, 2, '&nbsp;مالِک خُدائ تپوس وکړو، ”اے عاموسه، تا څۀ وليدل؟“ نو ما ورته جواب ورکړو، ”د پخې مېوې ډکه ټوکرۍ مې وليدله.“ بيا مالِک خُدائ ما ته وفرمائيل، ”زما د خلقو بنى اِسرائيلو دپاره وخت پوخ شوے دے، زۀ به نور هغوئ د سزا نه بغېر نۀ پرېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21369, 'Amos 8:3', 'Amos', 8, 3, '&nbsp;قادر مطلق خُدائ فرمائى، ”په هغه ورځ، به د عبادتخانې سندرې په ژړا او ماتم بدلې شى. ډېر مړى به په هر ځائ کښې په خاموشۍ پراتۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21370, 'Amos 8:4', 'Amos', 8, 4, '&nbsp;واورئ اے هغه خلقو څوک چې ضرورتمند راغورزوئ او د مُلک غريبانان تباه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21371, 'Amos 8:5', 'Amos', 8, 5, '&nbsp;تاسو خپل ځان سره وايئ چې، ”کله به د نوې مياشت ورځ ختمه شى او کله به د سبت ورځ تېره شى چې مونږ خپل د غلې ګودامونه کولاو کړُو او غله خرڅه کړُو؟ او مونږ ناپ تول کښې چل وَل وکړُو، او د څيزونو قيمتونه اوچت کړُو، او په تله کښې ټګى او دوکه وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21372, 'Amos 8:6', 'Amos', 8, 6, '&nbsp;غريبانان په سپينو زرو او ضرورتمند په يوه جوړه څپلو اخلو، او غنم هم د بوسو سره خرڅوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21373, 'Amos 8:7', 'Amos', 8, 7, '&nbsp;هغه مالِک خُدائ چې يعقوب ورباندې فخر کوى قسم وکړو چې، ”زۀ به هيڅکله هغه کارونه هېر نۀ کړم چې دوئ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21374, 'Amos 8:8', 'Amos', 8, 8, '&nbsp;د دې په وجه به زمکه ولړزيږى او څوک هم چې په دې مُلک کښې اوسيږى هغه به ماتم کوى. لکه څنګه چې په مِصر کښې د نيل درياب د سېلاب په وخت کښې اوچتيږى داسې به ټوله زمکه اوچته شى، او بيا به دوباره کښېنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21375, 'Amos 8:9', 'Amos', 8, 9, '&nbsp;مالِک قادر مطلق خُدائ فرمائى، ”په هغه ورځ به زۀ نمر په نيمه ورځ ښکته کړم او په زمکه به په رڼا ورځ تيارۀ راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21376, 'Amos 8:10', 'Amos', 8, 10, '&nbsp;زۀ به ستاسو مذهبى اخترونه په ماتم بدل کړم او ستاسو د خوشحالۍ ټولې سندرې به د غم په سندرو بدلې کړم. زۀ به په ټولو د ټاټ جامې واغوندمه او سرونه به پرې ګنجيان کړم. خلق به داسې ماتم کوى لکه چې اېک يو زوئ يې مړ وى. هغه ورځ به څومره سخته وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21377, 'Amos 8:11', 'Amos', 8, 11, '&nbsp;قادر مطلق خُدائ فرمائى، ”هغه ورځې راروانې دى، کله چې زۀ په زمکه باندې قحط راولم. خو دا به د لوږې او تندې قحط نۀ وى، بلکې دا به د خُدائ پاک د کلام د نۀ اورېدلو قحط وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21378, 'Amos 8:12', 'Amos', 8, 12, '&nbsp;خلق به د يو سمندر نه بل سمندر پورې او د شمال نه تر مشرق پورې ګرځى، چې د مالِک خُدائ کلام ولټوى، خو دوئ به يې پېدا نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21379, 'Amos 8:13', 'Amos', 8, 13, '&nbsp;په هغه ورځ به ښائسته پېغلې او ځوانان د تندې نه بې‌هوشه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21380, 'Amos 8:14', 'Amos', 8, 14, '&nbsp;کوم خلق چې د سامريه په شرمېدلو بُتانو قسم خورى، او يا وائى چې اے دان، زمونږ دې ستا په خُدائ قسم وى، او يا وائى چې اے بيرسبع، زمونږ دې ستا په خُدائ قسم وى، نو داسې خلق به راوغورزيږى او بيا به د پاڅېدو جوګه نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21381, 'Amos 9:1', 'Amos', 9, 1, '&nbsp;ما وليدل چې مالِک خُدائ د قربان‌ګاه سره ولاړ وو. او هغۀ وفرمائيل چې، ”د عبادتګاه د ستنو پاس سرونه ووهئ چې بنيادونه يې ولړزيږى. د خلقو په سرونو يې ښکته راوغورزوئ، څوک چې ژوندى پاتې شى هغوئ به زۀ په تُوره مړۀ کړم. يو به هم ونۀ تښتى، او هيڅ څوک به پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21382, 'Amos 9:2', 'Amos', 9, 2, '&nbsp;کۀ هغوئ زمکه وکنى او لاندې عالمِ ارواح ته هم کوز شى، نو زما لاسونه به يې د هلته نه هم راوباسى. کۀ هغوئ آسمان ته هم وخېژى، نو زۀ به يې هلته نه ښکته راکوز کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21383, 'Amos 9:3', 'Amos', 9, 3, '&nbsp;کۀ هغوئ د کرمل غر په سر هم خپل ځانونه پټ کړى، زۀ به يې هلته هم ولټوم او راګېر به يې کړم. کۀ هغوئ زما نه د سمندر په بېخ کښې پټ شى، نو زۀ به هلته سمندرى مار له حُکم ورکړم چې وې چيچى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21384, 'Amos 9:4', 'Amos', 9, 4, '&nbsp;کۀ د هغوئ دشمنان هغوئ جلاوطن کړى، نو هلته به زۀ تُورې ته د هغوئ د قتلولو حُکم ورکړم. زۀ به خپل نظر په هغوئ وساتم د هغوئ د فائدې دپاره نه بلکې د هغوئ د نقصان دپاره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21385, 'Amos 9:5', 'Amos', 9, 5, '&nbsp;مالِک خُدائ، ربُ الافواج خُدائ، چې زمکې له لاس وروړى نو زمکه ويلى شى. او د هغې ټول خلق ماتم کوى. ټوله زمکه داسې اوچتيږى لکه څنګه چې د سېلاب په وخت دريائے نيل راوچتيږى، او بيا واپس ښکته کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21386, 'Amos 9:6', 'Amos', 9, 6, '&nbsp;د مالِک خُدائ محل بره تر آسمانه پورې رسيږى، او د هغې بنياد يې په زمکه اېښے دے، هغه د سمندر نه اوبۀ راوباسى او د باران په شکل يې دوباره په زمکه راوروى. د هغۀ نوم مالِک خُدائ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21387, 'Amos 9:7', 'Amos', 9, 7, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، ولې تاسو ګنې ما ته د ايتهوپيا د خلقو نه ډېر اهم نۀ يئ څۀ؟ ما بنى اِسرائيل د مِصر نه راوويستل، خو ما فلستيان هم د کريتې نه او آراميان مې د قير نه هم راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21388, 'Amos 9:8', 'Amos', 9, 8, '&nbsp;ګوره، زۀ قادر مطلق خُدائ د بنى اِسرائيلو ګناهګاره قوم وينم. زۀ به دا د زمکې د مخ نه ختم کړم. خو زۀ به هيڅکله د يعقوب خاندان مکمل نۀ ختموم. مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21389, 'Amos 9:9', 'Amos', 9, 9, '&nbsp;نو زۀ به حُکم ورکړم، او زۀ به د بنى اِسرائيلو قوم په نورو قومونو کښې داسې چاڼ کړم لکه څنګه چې په چج غله چاڼ کيږى، او يو کاڼے به هم په غله کښې ترې نه لاړ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21390, 'Amos 9:10', 'Amos', 9, 10, '&nbsp;ټول ګناه ګار چې زما په خلقو کښې دى په تُوره به مړۀ شى، هغوئ ټول به مړۀ شى چې داسې وائى، نۀ به په مونږ افت راځى او نۀ به تباه کيږُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21391, 'Amos 9:11', 'Amos', 9, 11, '&nbsp;په هغه ورځ به زۀ د داؤد نړېدلے کور بيا آباد کړم. زۀ به د دې خراب شوى دېوالونه جوړ کړم او کنډر به يې بيا ودان کړم او لکه د پخوا په شان به يې بيا آباد کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21392, 'Amos 9:12', 'Amos', 9, 12, '&nbsp;نو بنى اِسرائيل به د ادوم په پاتې ځايونو قبضه وکړى او په ټولو هغه قومونو به قبضه وکړى چې زما په نوم دى.“ دا د مالِک خُدائ فرمان دے، څوک چې به دا هر څۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21393, 'Amos 9:13', 'Amos', 9, 13, '&nbsp;مالِک خُدائ فرمائى چې، ”هغه ورځې راروانې دى چې فصلونه به ډېر زيات وى. او فصل رېبلو له به دومره وخت پکار وى چې قُلبه کوونکى به فصل رېبونکو پسې زمکه تياروى. د انګورو فصل به هم، هم داسې وى، د انګورو د زياتوالى په وجه به د هغې نه د رس ويستلو دپاره دومره وخت پکار وى چې ورسره به تخم کرونکى خپل کر شروع کړى. د زياتوالى له وجې به نوى مے د غرونو نه راڅاڅى او د ټولو غونډو نه به رابهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21394, 'Amos 9:14', 'Amos', 9, 14, '&nbsp;زۀ به خپل جلاوطنه خلق بنى اِسرائيل واپس راولم، هغوئ به خپل کنډر شوى ښارونه بيا آباد کړى او په کښې به اوسيږى، هغوئ به د انګورو باغونه وکَرى او د دې مے به څښى، هغوئ به باغونه وکَرى او د دې مېوه به خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21395, 'Amos 9:15', 'Amos', 9, 15, '&nbsp;زۀ به بنى اِسرائيل د هغوئ په خپل مُلک کښې وکَرم، او دوئ به هيڅکله بيا د بېخ نه راونۀ ويستلے شى د هغه مُلک نه چې ما ورته ورکړے دے،“ ستاسو مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21396, 'Obadiah 1:1', 'Obadiah', 1, 1, '&nbsp;دا د عبدياه رويا ده. دا هغه څۀ دى چې مالِک خُدائ يې د ادوم د قوم په حقله فرمائى، مونږ د مالِک خُدائ نه يو پېغام واورېدو، هغۀ يو پېغمبر قومونو ته ولېږلو چې ورته وفرمائى، ”پاڅئ، او راځئ چې په ادوم حمله وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21397, 'Obadiah 1:2', 'Obadiah', 1, 2, '&nbsp;اے ادومه ګوره، زۀ به تا په قومونو کښې وړوکے کړم، تۀ به ډېر سپک شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21398, 'Obadiah 1:3', 'Obadiah', 1, 3, '&nbsp;تۀ خپل غرور دوکه کړے يې، تۀ چې د غرونو په غارونو کښې اوسېږې، او په اوچتو ځايونو کښې خپل کور جوړوې، تۀ چې د خپل ځان سره وائې چې، ”څوک ما لاندې زمکې ته راوستلے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21399, 'Obadiah 1:4', 'Obadiah', 1, 4, '&nbsp;خو تر دې کۀ تاسو د باز په شان اوچت هم والوځئ، او خپله جاله د ستورو سره جوړه کړئ، نو زۀ به هلته نه هم تاسو لاندې راولم، مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21400, 'Obadiah 1:5', 'Obadiah', 1, 5, '&nbsp;کۀ غلۀ د شپې راشى او تا لوټ کړى، نو هغوئ به تا نه دومره څۀ پټ کړى څومره چې غواړى. کله چې خلق انګور راټولوى نو څۀ نه څۀ ترې نه پاتې شى. خو ستاسو دشمن به تاسو مکمل جارُو کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');